(5624093, 816693, 31535, '<td valign="top">Clearly shows drama, or sadness in this case. Technically, the composition isn''t strong and the BG distracts from your main subjects.</td>', 'Clearly shows drama, or sadness in this case. Technically, the composition isn''t strong and the BG distracts from your main subjects.', '2009-08-26 01:33:12.000000', NULL, 1),
