(5625618, 815814, 108564, '<td valign="top">oooohhh - - I like this a lot!!!  That shadowy figure in the background makes me want to scream, "no kitty - don''t go that way!!!"  Very sinister feel to it - - WELL DONE!</td>', 'oooohhh - - I like this a lot!!!  That shadowy figure in the background makes me want to scream, "no kitty - don''t go that way!!!"  Very sinister feel to it - - WELL DONE!', '2009-08-26 23:16:59.000000', NULL, 1),
(5625622, 816712, 108564, '<td valign="top">Very noir : )   This is a great shot and a great idea.  I hope it does well.  I give you a 10!</td>', 'Very noir : )   This is a great shot and a great idea.  I hope it does well.  I give you a 10!', '2009-08-26 23:19:01.000000', NULL, 1),
(5625626, 816103, 108564, '<td valign="top">This soooooooo reminds me of The Wizard of Oz.  I expect Dorothy and Toto to be running through the gate at any moment.  Lovely composition and great sky!  10!</td>', 'This soooooooo reminds me of The Wizard of Oz.  I expect Dorothy and Toto to be running through the gate at any moment.  Lovely composition and great sky!  10!', '2009-08-26 23:20:43.000000', NULL, 1),
(5625638, 816095, 108564, '<td valign="top">Beautifully done!  Can''t say anything else - 10!</td>', 'Beautifully done!  Can''t say anything else - 10!', '2009-08-26 23:26:47.000000', NULL, 1),
(5625658, 816921, 108564, '<td valign="top">Totally awesome!!!  Great way of showing environmental drama as well as the way it affects humans.  Hope nothing actually burned down : )  Oh, yeah, by the way - 10!</td>', 'Totally awesome!!!  Great way of showing environmental drama as well as the way it affects humans.  Hope nothing actually burned down : )  Oh, yeah, by the way - 10!', '2009-08-26 23:38:46.000000', NULL, 1),
