(5625662, 815765, 108564, '<td valign="top">This rocks!  I love the tonal contrast, the composition and the fork!  10!</td>', 'This rocks!  I love the tonal contrast, the composition and the fork!  10!', '2009-08-26 23:40:50.000000', NULL, 1),
(5625675, 816264, 108564, '<td valign="top">Awesome subject - I hope that is his real name because it rocks! Fab fab fab - 10!</td>', 'Awesome subject - I hope that is his real name because it rocks! Fab fab fab - 10!', '2009-08-26 23:47:47.000000', NULL, 1),
