(5625698, 816467, 26464, '<td valign="top">i''d just pull the handbrake.</td>', 'i''d just pull the handbrake.', '2009-08-26 23:57:16.000000', NULL, 1),
(5625699, 816574, 26464, '<td valign="top">what? really?</td>', 'what? really?', '2009-08-26 23:57:55.000000', NULL, 1),
(5625713, 816117, 26464, '<td valign="top">hope this isn''t the ''before'' of another challenge shot called ''airshow disaster''</td>', 'hope this isn''t the ''before'' of another challenge shot called ''airshow disaster''', '2009-08-27 00:22:18.000000', NULL, 1),
(5625733, 816895, 108351, '<td valign="top">I like the concept and the title. Good job getting exposure on the subjects face and some light on the books with the bare lamp blazing into the lens.</td>', 'I like the concept and the title. Good job getting exposure on the subjects face and some light on the books with the bare lamp blazing into the lens.', '2009-08-27 01:00:03.000000', NULL, 1),
(5625734, 816805, 108351, '<td valign="top">Sharp right where it needs to be. Very nice.</td>', 'Sharp right where it needs to be. Very nice.', '2009-08-27 01:01:09.000000', NULL, 1),
(5625735, 816008, 108351, '<td valign="top">The flare, the harsh light, and the grain add to the drama on the subjects face. Very nice.</td>', 'The flare, the harsh light, and the grain add to the drama on the subjects face. Very nice.', '2009-08-27 01:02:35.000000', NULL, 1),
(5625737, 816701, 108351, '<td valign="top">A more shallow DOF would help to keep attention on the subject on not the leaves or the arch behind her.</td>', 'A more shallow DOF would help to keep attention on the subject on not the leaves or the arch behind her.', '2009-08-27 01:04:08.000000', NULL, 1),
(5625741, 815814, 108351, '<td valign="top">The cats crouch, and the OOF person on the right add tension to this scene. I think bit more light on the person (still OOF) would have made that a stronger element in the composition.</td>', 'The cats crouch, and the OOF person on the right add tension to this scene. I think bit more light on the person (still OOF) would have made that a stronger element in the composition.', '2009-08-27 01:07:28.000000', NULL, 1),
(5625743, 816132, 108351, '<td valign="top">More symmetry, or alot less would have made the composition stronger in my opinion.</td>', 'More symmetry, or alot less would have made the composition stronger in my opinion.', '2009-08-27 01:11:37.000000', NULL, 1),
(5625746, 816103, 108351, '<td valign="top">Those dark clouds add tension. Very nice.</td>', 'Those dark clouds add tension. Very nice.', '2009-08-27 01:12:25.000000', NULL, 1),
(5625747, 816770, 104358, '<td valign="top">Love the man-made to nature-made interface. Sky looks a bit noisy, eh?</td>', 'Love the man-made to nature-made interface. Sky looks a bit noisy, eh?', '2009-08-27 01:15:27.000000', NULL, 1),
(5625748, 815819, 108351, '<td valign="top">and the crown royal?</td>', 'and the crown royal?', '2009-08-27 01:16:33.000000', NULL, 1),
(5625749, 815867, 108351, '<td valign="top">Very nice. The only thing that I would try, and maybe you did, was to push the empty swings so they would be askew in the photo.</td>', 'Very nice. The only thing that I would try, and maybe you did, was to push the empty swings so they would be askew in the photo.', '2009-08-27 01:17:54.000000', NULL, 1),
(5625755, 816677, 108351, '<td valign="top">Which fire was this? The LaBrea fire (california) was burning about 25mi from here a week ago, and I thought there would be some drama to photograph there, but thought it better to stay out of the way.<br/>Very nice shot. Sharp all over, even with the smoke.</td>', 'Which fire was this? The LaBrea fire (california) was burning about 25mi from here a week ago, and I thought there would be some drama to photograph there, but thought it better to stay out of the way.Very nice shot. Sharp all over, even with the smoke.', '2009-08-27 01:25:04.000000', NULL, 1),
(5625757, 816304, 108351, '<td valign="top">Nice use of focus to let the viewer know exactly what the subject is.</td>', 'Nice use of focus to let the viewer know exactly what the subject is.', '2009-08-27 01:26:35.000000', NULL, 1),
(5625759, 815786, 108351, '<td valign="top">It is a bit difficult to tell what the primary subject is in this photo. The apples are obscured by leaves, but in focus, and the boy is easier to see but out of focus.</td>', 'It is a bit difficult to tell what the primary subject is in this photo. The apples are obscured by leaves, but in focus, and the boy is easier to see but out of focus.', '2009-08-27 01:27:51.000000', NULL, 1),
(5625764, 816117, 108351, '<td valign="top">Looking at this makes me nervous. And the perspective adds to the uncertainty of how close the planes actually are. Very well done.</td>', 'Looking at this makes me nervous. And the perspective adds to the uncertainty of how close the planes actually are. Very well done.', '2009-08-27 01:31:13.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5625765, 816894, 108351, '<td valign="top">Something to give these awesome clouds reference could have added to this picture and the intensity of The Storm. Without a reference it is quite abstract.</td>', 'Something to give these awesome clouds reference could have added to this picture and the intensity of The Storm. Without a reference it is quite abstract.', '2009-08-27 01:33:41.000000', NULL, 1),
(5625768, 816264, 108351, '<td valign="top">Those eyes make me want to look off of the near (left) side of the photo. A slightly different comp (subject on the right third) that made you look across to the far side (left) could have added to this photo. Just an idea.</td>', 'Those eyes make me want to look off of the near (left) side of the photo. A slightly different comp (subject on the right third) that made you look across to the far side (left) could have added to this photo. Just an idea.', '2009-08-27 01:36:42.000000', NULL, 1),
