(5628668, 816533, 96942, '<td valign="top">DNMC - Not the least bit compelling. Please review challenge description.</td>', 'DNMC - Not the least bit compelling. Please review challenge description.', '2009-08-30 22:50:16.000000', NULL, 1),
(5628980, 815887, 53316, '<td valign="top">The grain in this image is ABSOLUTELY PERFECT - don''t let anyone tell you differently.  Lighting is wonderful, composition is wonderful... sadly, this is one of those images that is underappreciated here at DPC because the technicals don''t follow "the rules" - but breaking the rules works very, very well in some instances, like here.</td>', 'The grain in this image is ABSOLUTELY PERFECT - don''t let anyone tell you differently.  Lighting is wonderful, composition is wonderful... sadly, this is one of those images that is underappreciated here at DPC because the technicals don''t follow "the rules" - but breaking the rules works very, very well in some instances, like here.', '2009-08-31 03:03:49.000000', NULL, 1),
(5628982, 816071, 53316, '<td valign="top">Wow, absolutely stunning. The composition is very dramatic and I love the contrast and colors as well.</td>', 'Wow, absolutely stunning. The composition is very dramatic and I love the contrast and colors as well.', '2009-08-31 03:04:16.000000', NULL, 1),
(5629148, 816732, 107301, '<td valign="top">Wow!</td>', 'Wow!', '2009-08-31 08:10:38.000000', NULL, 1),
(5629495, 816332, 52549, '<td valign="top">Wow! Amazing shot!</td>', 'Wow! Amazing shot!', '2009-08-31 14:41:47.000000', NULL, 1),
(5629499, 815976, 52549, '<td valign="top">Gorgeous, simply gorgeous. Perfect lighting and perfect tones. Top 3.</td>', 'Gorgeous, simply gorgeous. Perfect lighting and perfect tones. Top 3.', '2009-08-31 14:46:06.000000', NULL, 1),
(5629500, 815878, 52549, '<td valign="top">Great expression, very good image.</td>', 'Great expression, very good image.', '2009-08-31 14:46:39.000000', NULL, 1),
(5629508, 815496, 52549, '<td valign="top">Love it. Good luck!</td>', 'Love it. Good luck!', '2009-08-31 14:51:43.000000', NULL, 1),
(5629517, 816732, 52549, '<td valign="top">Fantastic! A tad oversharpened on my screen but a great shot nonetheless.</td>', 'Fantastic! A tad oversharpened on my screen but a great shot nonetheless.', '2009-08-31 14:54:16.000000', NULL, 1),
(5629521, 816400, 52549, '<td valign="top">Don''t know exactly why but I LOVE this shot ;-) Good luck!</td>', 'Don''t know exactly why but I LOVE this shot ;-) Good luck!', '2009-08-31 14:55:27.000000', NULL, 1),
(5629528, 816899, 52549, '<td valign="top">I think I recognize your wig ;-)))</td>', 'I think I recognize your wig ;-)))', '2009-08-31 14:57:40.000000', NULL, 1),
(5629530, 816684, 52549, '<td valign="top">Love the starkness (hope that''s a word ;-).</td>', 'Love the starkness (hope that''s a word ;-).', '2009-08-31 14:58:30.000000', NULL, 1),
(5629531, 816919, 52549, '<td valign="top">Excellent take on the challenge.</td>', 'Excellent take on the challenge.', '2009-08-31 14:58:43.000000', NULL, 1),
(5629542, 816468, 52549, '<td valign="top">Don''t know how well statues go down on dpc but I really like this.</td>', 'Don''t know how well statues go down on dpc but I really like this.', '2009-08-31 15:03:42.000000', NULL, 1),
(5629547, 816095, 52549, '<td valign="top">Great face, wonderful portrait. If I had anything to criticize about it at all, it would be the OOF hand on the left, but it''s no big deal.</td>', 'Great face, wonderful portrait. If I had anything to criticize about it at all, it would be the OOF hand on the left, but it''s no big deal.', '2009-08-31 15:06:52.000000', NULL, 1),
(5629550, 816702, 46918, '<td valign="top">I think that the paper is kindof blown. The " F" should pop out more to the viewer...</td>', 'I think that the paper is kindof blown. The " F" should pop out more to the viewer...', '2009-08-31 15:08:39.000000', NULL, 1),
(5629552, 815898, 52549, '<td valign="top">Wonderful! Definitely one of my favourites in this challenge. Hope for front page for you.</td>', 'Wonderful! Definitely one of my favourites in this challenge. Hope for front page for you.', '2009-08-31 15:09:30.000000', NULL, 1),
(5629553, 816712, 52549, '<td valign="top">The feet and legs don''t look real to me but that''s exactly what makes this shot so fascinating. Great work.</td>', 'The feet and legs don''t look real to me but that''s exactly what makes this shot so fascinating. Great work.', '2009-08-31 15:11:03.000000', NULL, 1),
(5629593, 816562, 10785, '<td valign="top">This is obvious drama and a high quality shot. I gave it an 8 and here''s why I didn''t mark it higher: I thought the shot was a little too sharp and could have benefited from being softened up a bit. Also I thought the fact it was shot from a little far away using a higher aperture setting brought everything in focus. I think the shot could have benefitted if one of the subjects was closer to you while the remaining subjects were farther away and a little blurred using a wider Depth of Field.</td>', 'This is obvious drama and a high quality shot. I gave it an 8 and here''s why I didn''t mark it higher: I thought the shot was a little too sharp and could have benefited from being softened up a bit. Also I thought the fact it was shot from a little far away using a higher aperture setting brought everything in focus. I think the shot could have benefitted if one of the subjects was closer to you while the remaining subjects were farther away and a little blurred using a wider Depth of Field.', '2009-08-31 15:47:40.000000', NULL, 1),
(5629733, 816712, 36981, '<td valign="top">I love this ...</td>', 'I love this ...', '2009-08-31 18:30:01.000000', NULL, 1),
(5629756, 815765, 109732, '<td valign="top">I like this picture.</td>', 'I like this picture.', '2009-08-31 19:08:21.000000', NULL, 1),
(5629777, 816293, 92577, '<td valign="top">fulfills requirement for drama. Shame it''s not sharper. IMHO the tilt could add more drama if it were more exaggerated and deliberate looking. good luck</td>', 'fulfills requirement for drama. Shame it''s not sharper. IMHO the tilt could add more drama if it were more exaggerated and deliberate looking. good luck', '2009-08-31 19:32:08.000000', NULL, 1),
(5629778, 816117, 92577, '<td valign="top">wow! I hope they survived. true drama</td>', 'wow! I hope they survived. true drama', '2009-08-31 19:33:43.000000', NULL, 1),
(5629782, 816264, 92577, '<td valign="top">good portrait - slightly odd comp</td>', 'good portrait - slightly odd comp', '2009-08-31 19:37:10.000000', NULL, 1),
(5629783, 816608, 92577, '<td valign="top">great</td>', 'great', '2009-08-31 19:37:35.000000', NULL, 1),
(5629787, 816304, 92577, '<td valign="top">v. good</td>', 'v. good', '2009-08-31 19:38:22.000000', NULL, 1),
(5629792, 815267, 92577, '<td valign="top">shame this doesn''t look bigger cos it''s great</td>', 'shame this doesn''t look bigger cos it''s great', '2009-08-31 19:44:26.000000', NULL, 1),
(5629796, 816695, 92577, '<td valign="top">dramatic</td>', 'dramatic', '2009-08-31 19:46:28.000000', NULL, 1),
(5629800, 816264, 106349, '<td valign="top">Great portrait, doesn''t really make me think "drama"</td>', 'Great portrait, doesn''t really make me think "drama"', '2009-08-31 19:56:55.000000', NULL, 1),
(5629803, 816400, 106349, '<td valign="top">Adorable, doesn''t really make me think of "drama" so I knocked my score down one point - 6</td>', 'Adorable, doesn''t really make me think of "drama" so I knocked my score down one point - 6', '2009-08-31 19:58:11.000000', NULL, 1),
(5629804, 816820, 106349, '<td valign="top">Beautiful picture... but I don''t see it as dramatic at all.</td>', 'Beautiful picture... but I don''t see it as dramatic at all.', '2009-08-31 19:58:37.000000', NULL, 1),
(5629805, 816691, 106349, '<td valign="top">This is a very beautiful shot. The "drama" isn''t really visual but I can only imagine how dramatic the music itself is.</td>', 'This is a very beautiful shot. The "drama" isn''t really visual but I can only imagine how dramatic the music itself is.', '2009-08-31 19:59:58.000000', NULL, 1),
(5629806, 815983, 106349, '<td valign="top">The lighting on this is gorgeous.</td>', 'The lighting on this is gorgeous.', '2009-08-31 20:00:29.000000', NULL, 1),
(5629809, 816732, 106349, '<td valign="top">Holy cow! That''s an amazing shot!</td>', 'Holy cow! That''s an amazing shot!', '2009-08-31 20:04:16.000000', NULL, 1),
(5629810, 816278, 106349, '<td valign="top">It''s slightly creepy... :o)</td>', 'It''s slightly creepy... :o)', '2009-08-31 20:05:26.000000', NULL, 1),
(5629849, 816642, 87252, '<td valign="top">Ha! Nice idea - the lighting may be a bit flat though.</td>', 'Ha! Nice idea - the lighting may be a bit flat though.', '2009-08-31 21:26:40.000000', NULL, 1),
(5629850, 816691, 87252, '<td valign="top">Lovely portrait - possibly slightly more sombre than dramatic but I like the processing.</td>', 'Lovely portrait - possibly slightly more sombre than dramatic but I like the processing.', '2009-08-31 21:27:34.000000', NULL, 1),
(5629851, 815819, 87252, '<td valign="top">I see the face - I''m glad someone else has an abstract mind on here!</td>', 'I see the face - I''m glad someone else has an abstract mind on here!', '2009-08-31 21:28:17.000000', NULL, 1),
(5629852, 815983, 87252, '<td valign="top">Really lovely shot but I''m afraid you''re going to lose out here on "obvious" drama points.</td>', 'Really lovely shot but I''m afraid you''re going to lose out here on "obvious" drama points.', '2009-08-31 21:29:51.000000', NULL, 1),
(5629856, 815814, 87252, '<td valign="top">This rocks - sinister with a hint of potential danger - just how most cats must view next-door''s garden. Great shot on the nose of the challenge.</td>', 'This rocks - sinister with a hint of potential danger - just how most cats must view next-door''s garden. Great shot on the nose of the challenge.', '2009-08-31 21:32:32.000000', NULL, 1),
(5629857, 816400, 87252, '<td valign="top">Not really that dramatic but nice shot.</td>', 'Not really that dramatic but nice shot.', '2009-08-31 21:33:14.000000', NULL, 1),
(5629858, 816696, 87252, '<td valign="top">Nice idea - maybe a bit too much empty space top right.</td>', 'Nice idea - maybe a bit too much empty space top right.', '2009-08-31 21:34:10.000000', NULL, 1),
(5629860, 816754, 87252, '<td valign="top">I love cloud shots but you''ve not quite nailed the exposure properly here - the highlights are blown out and you''ve lost a lot of detail by bumping up the contrast. Dramatic skies are great though - never the same, always beautiful.</td>', 'I love cloud shots but you''ve not quite nailed the exposure properly here - the highlights are blown out and you''ve lost a lot of detail by bumping up the contrast. Dramatic skies are great though - never the same, always beautiful.', '2009-08-31 21:36:18.000000', NULL, 1),
(5629861, 816409, 87252, '<td valign="top">Sweet, great spot.</td>', 'Sweet, great spot.', '2009-08-31 21:36:34.000000', NULL, 1),
(5629863, 816894, 87252, '<td valign="top">Lovely clouds - well composed too.</td>', 'Lovely clouds - well composed too.', '2009-08-31 21:37:03.000000', NULL, 1),
(5629864, 815216, 87252, '<td valign="top">A bit too "snapshotty" for me, nice idea though.</td>', 'A bit too "snapshotty" for me, nice idea though.', '2009-08-31 21:37:32.000000', NULL, 1),
(5629866, 816919, 87252, '<td valign="top">Cool abstract, maybe a bit too "out there" for this challenge though.</td>', 'Cool abstract, maybe a bit too "out there" for this challenge though.', '2009-08-31 21:38:10.000000', NULL, 1),
(5629868, 816684, 87252, '<td valign="top">Nice idea but the mask is maybe a bit too everyday for this to really score well. Good lighting set up - If you''d cropped this shot to the area just around the left eye of the mask it might have bumped it up on the dramatic scale!</td>', 'Nice idea but the mask is maybe a bit too everyday for this to really score well. Good lighting set up - If you''d cropped this shot to the area just around the left eye of the mask it might have bumped it up on the dramatic scale!', '2009-08-31 21:40:21.000000', NULL, 1),
(5629871, 815898, 87252, '<td valign="top">Very well-lit portrait of a striking and distinguished face. You''ve picked out the contours of his shoulders and neck superbly.</td>', 'Very well-lit portrait of a striking and distinguished face. You''ve picked out the contours of his shoulders and neck superbly.', '2009-08-31 21:41:45.000000', NULL, 1),
(5629872, 816541, 87252, '<td valign="top">Great shot - I can feel the anticipation. I think this would look great in a higher res.</td>', 'Great shot - I can feel the anticipation. I think this would look great in a higher res.', '2009-08-31 21:42:36.000000', NULL, 1),
(5629873, 815640, 87252, '<td valign="top">Spooky... cool shot.</td>', 'Spooky... cool shot.', '2009-08-31 21:43:14.000000', NULL, 1),
(5629874, 816680, 87252, '<td valign="top">Very dramatic - I''m sure this will do well.</td>', 'Very dramatic - I''m sure this will do well.', '2009-08-31 21:43:57.000000', NULL, 1),
(5629880, 816732, 87252, '<td valign="top">Great shot - you''ve really brought out the details nicely on the smoke. I''ve got the feeling this will be near the front page. Funny that these guys got two DPCers on the same challenge - I bow to your superior shot!</td>', 'Great shot - you''ve really brought out the details nicely on the smoke. I''ve got the feeling this will be near the front page. Funny that these guys got two DPCers on the same challenge - I bow to your superior shot!', '2009-08-31 21:46:59.000000', NULL, 1),
(5629882, 815306, 87252, '<td valign="top">These look like they''ve seen some drama.</td>', 'These look like they''ve seen some drama.', '2009-08-31 21:47:37.000000', NULL, 1),
(5629885, 816695, 87252, '<td valign="top">Nice idea but it does seem a little too contrived. Also the composition isn''t quite there.</td>', 'Nice idea but it does seem a little too contrived. Also the composition isn''t quite there.', '2009-08-31 21:49:43.000000', NULL, 1),
(5629888, 816095, 87252, '<td valign="top">Oh wow, this is a truly stunning portrait. Definitely a fave and I hope this gets on the front page.</td>', 'Oh wow, this is a truly stunning portrait. Definitely a fave and I hope this gets on the front page.', '2009-08-31 21:51:39.000000', NULL, 1),
(5629889, 815860, 87252, '<td valign="top">Sweet, but not very dramatic - bit of a shoehorn IMO.</td>', 'Sweet, but not very dramatic - bit of a shoehorn IMO.', '2009-08-31 21:52:28.000000', NULL, 1),
(5629890, 816921, 87252, '<td valign="top">Er... that''s a go from me.</td>', 'Er... that''s a go from me.', '2009-08-31 21:52:57.000000', NULL, 1),
(5629891, 816386, 87252, '<td valign="top">Cool shot - would have been great to see more of the cloud - and you''ve chopped a man in half at the bottom!</td>', 'Cool shot - would have been great to see more of the cloud - and you''ve chopped a man in half at the bottom!', '2009-08-31 21:53:50.000000', NULL, 1),
(5629892, 815806, 87252, '<td valign="top">Great car shot.</td>', 'Great car shot.', '2009-08-31 21:54:08.000000', NULL, 1),
(5629894, 816103, 87252, '<td valign="top">Oooo creepy...</td>', 'Oooo creepy...', '2009-08-31 21:54:54.000000', NULL, 1),
(5629895, 816432, 87252, '<td valign="top">Wow, I think I''m going to have nightmares...</td>', 'Wow, I think I''m going to have nightmares...', '2009-08-31 21:55:28.000000', NULL, 1),
(5629898, 816540, 87252, '<td valign="top">Love the minimalism, brave shot for this challenge.</td>', 'Love the minimalism, brave shot for this challenge.', '2009-08-31 21:55:54.000000', NULL, 1),
(5629902, 815618, 87252, '<td valign="top">This is a bit too contrived for my taste and the composition needs a bit of work. Nice idea though!</td>', 'This is a bit too contrived for my taste and the composition needs a bit of work. Nice idea though!', '2009-08-31 21:57:21.000000', NULL, 1),
(5629903, 816071, 87252, '<td valign="top">Gotta love dramatic clouds.</td>', 'Gotta love dramatic clouds.', '2009-08-31 21:57:40.000000', NULL, 1),
(5629905, 815867, 87252, '<td valign="top">I like this shot - I think it would have been really great if you''d taken about 10 steps back and composed her on into the bottom right third of the shot - that would really have emphasised the loneliness/ sadness feel here I think.</td>', 'I like this shot - I think it would have been really great if you''d taken about 10 steps back and composed her on into the bottom right third of the shot - that would really have emphasised the loneliness/ sadness feel here I think.', '2009-08-31 22:00:22.000000', NULL, 1),
(5629908, 815267, 87252, '<td valign="top">Ooo the low res really kills this shot - I''m sure it looks stunning as a big picture.</td>', 'Ooo the low res really kills this shot - I''m sure it looks stunning as a big picture.', '2009-08-31 22:01:48.000000', NULL, 1),
